using System;using System.Linq;using System.IO;using UnityEngine;using EchoSphere.Core;using EchoSphere.Presentation;using Newtonsoft.Json;
public static class PlayerCopyInventory {
 public static object Main(){var a=Resources.Load<NativeArchiveCatalog>("EchoSphere/NativeArchiveCatalog");var l=NativeLocalizationCatalog.Instance;var p=Resources.Load<NativeProgressionCatalog>("EchoSphere/NativeProgressionCatalog");var run=NativeRunCatalog.Instance;
 var data=new{run=new{run.Spheres,run.Abilities,run.Artifacts,run.Synergies,run.Sets,run.Elements,run.Regions,run.RegionPhases,run.Runes,run.Rarities,run.SphereAbilityLinks},archive=new{a.Entries,a.Planner},localization=l.Translations,achievements=p.Achievements,characters=CharacterRules.All,artifacts=ArtifactRewardRules.Catalog(true),artifactOverrides=ArtifactRewardRules.Catalog(true).Select(x=>new{DescriptionRu=ArtifactGameplayRules.DescriptionOverride(x.Id,true),DescriptionEn=ArtifactGameplayRules.DescriptionOverride(x.Id,false)}).ToArray(),sets=CampaignArtifactSets.All,regions=CampaignRegions.Additional,protocols=ArtifactProtocolRules.Protocols,contracts=Enum.GetValues(typeof(EchoRegionId)).Cast<EchoRegionId>().SelectMany(CampaignRegionContent.GetContracts).ToArray(),currency=Enum.GetValues(typeof(CurrencyId)).Cast<CurrencyId>().Select(id=>new{NameRu=MetaCurrencyRules.Name(id,true),NameEn=MetaCurrencyRules.Name(id,false),DescriptionRu=MetaCurrencyRules.Purpose(id,true),DescriptionEn=MetaCurrencyRules.Purpose(id,false)}).ToArray(),runes=Enumerable.Range(0,RuneRules.Count).Select(i=>new{NameRu=RuneRules.Name(RuneRules.TypeAt(i),true),NameEn=RuneRules.Name(RuneRules.TypeAt(i),false),DescriptionRu=RuneRules.Description(RuneRules.TypeAt(i),true),DescriptionEn=RuneRules.Description(RuneRules.TypeAt(i),false)}).ToArray()};Directory.CreateDirectory("Library/player-copy");File.WriteAllText("Library/player-copy/inventory.json",JsonConvert.SerializeObject(data,Formatting.Indented));return "Exported player copy inventory";}
}
